def preserve_cattle_states(apps, schema_editor):
    Animal = apps.get_model("livestock", "Animal")
    Profile = apps.get_model("livestock", "CattleAnimalProfile")
    Event = apps.get_model("livestock", "HistoricoEvento")
    alias = schema_editor.connection.alias
    castrated = Event.objects.using(alias).filter(
        tipo_evento="Castração", matriz_id=models.OuterRef("pk")
    )
    animals = (
        Animal.objects.using(alias)
        .filter(species__code="bovinos")
        .annotate(was_castrated=models.Exists(castrated))
    )
    pending = []
    for animal in animals.iterator(chunk_size=500):
        pending.append(
            Profile(
                animal_id=animal.pk,
                is_lactating=animal.gender == "F"
                and animal.reproductive_status == "lactante",
                is_castrated=animal.was_castrated,
            )
        )
        if len(pending) == 500:
            Profile.objects.using(alias).bulk_create(pending)
            pending = []
    if pending:
        Profile.objects.using(alias).bulk_create(pending)


